<?php $id=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM news WHERE id=?');$s->execute([$id]);$n=$s->fetch();if(!$n){http_response_code(404);$title='Notizia non trovata';require __DIR__.'/404.php';exit;}require __DIR__.'/partials/header.php';?><section class="page-hero"><div class="wrap"><span class="eyebrow"><?= e($n['category']) ?> · <?= $n['is_demo']?'DEMO':'NEWS' ?></span><h1><?= e($n['title']) ?></h1><p><?= e(date('d F Y',strtotime($n['published_at']))) ?></p></div></section><article class="wrap article-body"><img class="article-cover" src="<?= e($n['image_url']?:'assets/images/basket.svg') ?>" alt="Immagine dimostrativa"><p class="lead"><?= e($n['excerpt']) ?></p><div><?= nl2br(e($n['body'])) ?></div><p class="fine-print">Contenuto dimostrativo modificabile dal database.</p><a class="btn btn-ghost" href="news.php">← Tutte le notizie</a></article><?php require __DIR__.'/partials/footer.php'; ?>